<template><div class="page-card contract-form-page" v-loading="loading"><div class="form-nav"><el-button :icon="ArrowLeft" @click="goBack">返回</el-button><span>{{isEdit?`编辑合同 ${form.code||''}`:'签订新合同'}}</span></div><el-alert v-if="selectedMerchant?.blacklisted" type="error" :closable="false" show-icon title="当前客户在黑名单中，合同只能保存为草稿，不能生效。" class="blacklist-alert"/><el-form ref="formRef" :model="form" :rules="rules" label-width="100px" class="contract-form"><section><header><span>合同双方</span><small>选择签约客户并记录签订日期</small></header><el-row :gutter="16"><el-col :span="14"><el-form-item label="签约客户" prop="merchantId"><el-select v-model="form.merchantId" filterable style="width:100%" :disabled="isEdit"><el-option v-for="m in lookup?.merchants||[]" :key="m.id" :value="m.id" :label="m.name+(m.blacklisted?'（黑名单）':'')"/></el-select></el-form-item></el-col><el-col :span="10"><el-form-item label="签订日期"><el-date-picker v-model="form.signDate" type="date" value-format="YYYY-MM-DD" style="width:100%"/></el-form-item></el-col></el-row></section><section><header><span>合同期限</span><small>多年合同按自然年度拆分应收</small></header><el-row :gutter="16"><el-col :span="12"><el-form-item label="起始日期" prop="startDate"><el-date-picker v-model="form.startDate" type="date" value-format="YYYY-MM-DD" style="width:100%" :disabled="isEdit"/></el-form-item></el-col><el-col :span="12"><el-form-item label="到期日期" prop="endDate"><el-date-picker v-model="form.endDate" type="date" value-format="YYYY-MM-DD" style="width:100%" :disabled="isEdit"/></el-form-item></el-col></el-row></section><section class="items-section"><header><span>广告牌与年度租金</span><small>一份合同可绑定多块广告牌，每块牌分别定价</small></header><div class="item-head"><span>广告牌</span><span>每年租金（元）</span><span></span></div><div v-for="(item,index) in form.items" :key="index" class="item-row"><el-select v-model="item.billboardId" filterable placeholder="选择广告牌" :disabled="isEdit"><el-option v-for="b in lookup?.billboards||[]" :key="b.id" :value="b.id" :label="`${b.code} · ${b.sectionName||''} · ${b.stakeActual||''}`" :disabled="!!form.items?.some((it,i)=>i!==index&&it.billboardId===b.id)"/></el-select><el-input-number v-model="item.yearlyPrice" :min="0" :step="1000" :controls="false"/><el-button v-if="!isEdit" link type="danger" :icon="Delete" @click="form.items?.splice(index,1)"/></div><el-button v-if="!isEdit" :icon="Plus" @click="form.items?.push({billboardId:null,yearlyPrice:null})">添加广告牌</el-button><div class="contract-total"><span>合同年限 <b>{{years}} 年</b></span><span>年度租金合计 <b>¥ {{fmtMoney(annualTotal)}}</b></span><span>合同总额 <strong>¥ {{fmtMoney(total)}}</strong></span></div></section><section><header><span>生效设置</span><small>生效后立即校验时间重叠并生成“年度 × 广告牌”应收账单</small></header><el-radio-group v-if="!isEdit" v-model="form.status"><el-radio value="草稿">保存为草稿</el-radio><el-radio value="生效" :disabled="selectedMerchant?.blacklisted">直接生效</el-radio></el-radio-group><el-alert v-else type="info" :closable="false" title="编辑页面只修改草稿合同；合同生效请回到合同列表操作。"/><el-form-item label="合同备注" class="remark"><el-input v-model="form.remark" type="textarea" :rows="3"/></el-form-item></section></el-form><footer><el-button @click="goBack">取消</el-button><el-button type="primary" :loading="saving" @click="save">保存合同</el-button></footer></div></template>
<script setup lang="ts">import{computed,onMounted,reactive,ref}from'vue';import{useRoute,useRouter}from'vue-router';import{ElMessage}from'element-plus';import type{FormInstance,FormRules}from'element-plus';import{ArrowLeft,Delete,Plus}from'@element-plus/icons-vue';import{contractApi,lookupApi}from'../api';import{fmtMoney}from'../utils/format';import type{Contract,LookupData}from'../types';const route=useRoute(),router=useRouter(),isEdit=computed(()=>!!route.params.id),loading=ref(false),saving=ref(false),formRef=ref<FormInstance>(),lookup=ref<LookupData|null>(null),form=reactive<Partial<Contract>>({items:[]});const selectedMerchant=computed(()=>lookup.value?.merchants.find(m=>m.id===form.merchantId));const years=computed(()=>form.startDate&&form.endDate?new Date(form.endDate).getFullYear()-new Date(form.startDate).getFullYear()+1:0),annualTotal=computed(()=>(form.items||[]).reduce((s,i)=>s+(i.yearlyPrice||0),0)),total=computed(()=>annualTotal.value*years.value);const rules:FormRules={merchantId:[{required:true,message:'请选择客户',trigger:'change'}],startDate:[{required:true,message:'请选择起始日期',trigger:'change'}],endDate:[{required:true,message:'请选择到期日期',trigger:'change'}],items:[{validator:(_r,value:Contract['items'],cb)=>{if(!value?.length)cb(new Error('至少绑定一块广告牌'));else if(value.some(i=>!i.billboardId))cb(new Error('存在未选择广告牌的明细'));else if(value.some(i=>!i.yearlyPrice||i.yearlyPrice<=0))cb(new Error('每块牌年租金必须大于0'));else cb()},trigger:'change'}]};function reset(){Object.assign(form,{merchantId:null,signDate:new Date().toISOString().slice(0,10),startDate:'',endDate:'',status:'草稿',remark:'',items:[{billboardId:null,yearlyPrice:null}]})}function goBack(){router.push(isEdit.value?`/contracts/${route.params.id}`:'/contracts')}async function save(){await formRef.value?.validate();saving.value=true;try{let row:Contract;if(isEdit.value)row=await contractApi.update(Number(route.params.id),form);else row=await contractApi.create(form);ElMessage.success(form.status==='生效'?'合同已生效并生成应收':'合同已保存');router.push(`/contracts/${row.id}`)}finally{saving.value=false}}onMounted(async()=>{loading.value=true;try{lookup.value=await lookupApi.all();reset();if(isEdit.value){const row=(await contractApi.list({})).find(item=>item.id===Number(route.params.id));if(row)Object.assign(form,JSON.parse(JSON.stringify(row)))}}finally{loading.value=false}});
</script>
<style scoped>.contract-form-page{max-width:1100px;margin:0 auto}.form-nav{display:flex;align-items:center;gap:14px;margin-bottom:18px;color:#526075}.blacklist-alert{margin-bottom:14px}.contract-form{border:1px solid #dbe3ed}.contract-form section{padding:19px 22px 16px;border-bottom:1px solid #dbe3ed}.contract-form section:last-child{border:0}.contract-form header{display:flex;align-items:baseline;gap:12px;margin-bottom:17px;padding-left:10px;border-left:3px solid #16488a}.contract-form header span{color:#173b64;font-size:16px;font-weight:650}.contract-form header small{color:#7b8797}.items-section{background:#f8fafc}.item-head,.item-row{display:grid;grid-template-columns:minmax(280px,1fr) 220px 40px;gap:10px;align-items:center}.item-head{margin-bottom:7px;color:#7a8797;font-size:12px}.item-row{margin-bottom:9px}.contract-total{display:flex;justify-content:flex-end;gap:28px;margin-top:18px;padding:14px 16px;border-top:1px solid #d7e0ea;background:#fff;color:#667386}.contract-total b{color:#24476f}.contract-total strong{color:#b66c00;font-size:18px}.remark{margin-top:16px}.contract-form-page footer{display:flex;justify-content:flex-end;gap:10px;margin-top:18px}@media(max-width:760px){.item-head{display:none}.item-row{grid-template-columns:1fr}.contract-total{align-items:flex-end;flex-direction:column;gap:7px}}</style>
